// Extract Instagram message data
const igMessage = $node["Instagram Webhook"].json;

const messageData = {
  id: igMessage.id || igMessage.message_id,
  from: igMessage.from || igMessage.sender_id,
  from_username: igMessage.from_username || igMessage.username,
  text: igMessage.text || igMessage.message,
  timestamp: igMessage.timestamp || new Date().toISOString(),
  media_url: igMessage.media_url || igMessage.image_url,
  message_type: igMessage.message_type || 'text'
};

// Validate message
if (!messageData.text || messageData.text.trim().length === 0) {
  return { valid: false, error: 'Empty message' };
}

// Check if it's a media-only message
if (messageData.message_type === 'image' && !messageData.text) {
  messageData.intent = 'image_only';
  messageData.confidence = 1.0;
  return { ...messageData, valid: true };
}

// Clean and normalize text
messageData.text_clean = messageData.text
  .toLowerCase()
  .trim()
  .replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{2600}-\u{26FF}]/gu, '') // Remove emojis
  .replace(/[^a-záéíóúâêôãõç\s]/g, ' ') // Keep only letters and spaces
  .replace(/\s+/g, ' ') // Normalize spaces
  .trim();

// Detect language (basic)
const portugueseWords = ['preço', 'valor', 'entrega', 'frete', 'tamanho', 'cor', 'pagamento', 'boleto', 'cartão', 'devolução', 'troca', 'garantia'];
const hasPortuguese = portugueseWords.some(word => messageData.text_clean.includes(word));
messageData.language = hasPortuguese ? 'pt' : 'unknown';

return { ...messageData, valid: true };

// Classify message intent using keyword matching
const text = $json.text_clean;

// Define intent patterns
const intentPatterns = {
  preco: {
    keywords: ['preço', 'valor', 'custa', 'quanto', 'price', 'cost', 'how much'],
    response: 'Para verificar preços, visite nossa loja online: https://getnexo.com.br. Temos opções para todos os bolsos! 💰',
    quick_replies: ['Ver produtos', 'Falar com humano']
  },
  entrega: {
    keywords: ['entrega', 'frete', 'envio', 'shipping', 'delivery', 'quando chega'],
    response: 'Oferecemos frete grátis para compras acima de R$200! 🚚\nEntrega em até 5 dias úteis.\nRastreie seu pedido em: https://getnexo.com.br/rastreamento',
    quick_replies: ['Calcular frete', 'Política de entrega']
  },
  tamanho: {
    keywords: ['tamanho', 'size', 'numero', 'medida', 'couro'],
    response: 'Confira nossa tabela de medidas na página do produto! 📏\nTemos tamanhos de 34 a 46.\nDúvidas? Nossa equipe ajuda! 👟',
    quick_replies: ['Tabela de medidas', 'Falar com consultor']
  },
  cor: {
    keywords: ['cor', 'color', 'preto', 'branco', 'azul', 'vermelho', 'verde'],
    response: 'Temos várias cores disponíveis! 🌈\nConfira as fotos do produto ou pergunte sobre disponibilidade.\nEstamos aqui para ajudar! 🎨',
    quick_replies: ['Ver fotos', 'Disponibilidade']
  },
  pagamento: {
    keywords: ['pagamento', 'pagar', 'boleto', 'cartão', 'credito', 'debito', 'pix', 'paypal'],
    response: 'Aceitamos cartão, boleto, PIX e PayPal! 💳\nParcelamento em até 12x sem juros.\nPagamento seguro e fácil! 🔒',
    quick_replies: ['Ver formas', 'Parcelamento']
  },
  devolucao: {
    keywords: ['devolução', 'troca', 'devolver', 'return', 'exchange', 'refund'],
    response: 'Garantia de 30 dias para troca/devolução! ↩️\nProduto deve estar novo, com nota fiscal.\nEntre em contato: suporte@getnexo.com.br',
    quick_replies: ['Política completa', 'Falar com suporte']
  },
  garantia: {
    keywords: ['garantia', 'defeito', 'quebrou', 'warranty', 'broken'],
    response: 'Garantia de 1 ano contra defeitos! 🛡️\nPara problemas, envie foto do produto e nota fiscal.\nResolveremos rapidinho! ⚡',
    quick_replies: ['Como acionar', 'Falar com suporte']
  },
  suporte: {
    keywords: ['ajuda', 'suporte', 'problema', 'duvida', 'help', 'support', 'issue'],
    response: 'Estamos aqui para ajudar! 💬\nComo posso te auxiliar hoje?',
    quick_replies: ['Falar com humano', 'Ver FAQ']
  },
  pedido: {
    keywords: ['pedido', 'order', 'status', 'onde esta', 'rastreamento'],
    response: 'Para acompanhar seu pedido, acesse: https://getnexo.com.br/meus-pedidos 📦\nOu me diga o número do pedido!',
    quick_replies: ['Acompanhar pedido', 'Falar com suporte']
  }
};

// Find matching intent
let bestMatch = null;
let bestScore = 0;
let matchedKeywords = [];

for (const [intent, data] of Object.entries(intentPatterns)) {
  let score = 0;
  const foundKeywords = [];

  for (const keyword of data.keywords) {
    if (text.includes(keyword)) {
      score += 1;
      foundKeywords.push(keyword);
    }
  }

  // Bonus for exact matches
  if (score > 0 && foundKeywords.length > 0) {
    score += 0.5; // Bonus por ter encontrado keywords
  }

  if (score > bestScore) {
    bestScore = score;
    bestMatch = intent;
    matchedKeywords = foundKeywords;
  }
}

// Determine confidence
const confidence = bestScore > 0 ? Math.min(bestScore / 3, 1) : 0;

let result = {
  intent: 'unknown',
  confidence: 0,
  response_text: 'Olá! Como posso ajudar você hoje? 😊',
  quick_replies: ['Ver produtos', 'Suporte', 'FAQs'],
  matched_keywords: [],
  needs_human: false
};

if (bestMatch && confidence >= 0.3) { // Threshold de confiança
  const intentData = intentPatterns[bestMatch];
  result = {
    intent: bestMatch,
    confidence: confidence,
    response_text: intentData.response,
    quick_replies: intentData.quick_replies,
    matched_keywords: matchedKeywords,
    needs_human: false
  };
} else {
  // Baixa confiança - encaminhar para humano
  result.needs_human = true;
  result.intent = 'low_confidence';
  result.response_text = 'Olá! Vou transferir você para um de nossos especialistas. Eles poderão ajudar melhor! 👨‍💼\n\nUm momento...';
  result.quick_replies = ['Aguardar atendimento'];
}

return result;

// Prepare automated response
const messageData = $node["Parse Instagram Message"].json;
const intentData = $json;

// Personalize response based on user
const personalizedResponse = intentData.response_text.replace('Olá', `Olá${messageData.from_username ? ' ' + messageData.from_username : ''}`);

// Add quick replies as buttons
const quickRepliesText = intentData.quick_replies.map(reply => `• ${reply}`).join('\n');
const fullResponse = `${personalizedResponse}\n\n${quickRepliesText}`;

// Create Instagram API response format
const responseData = {
  recipient_id: messageData.from,
  message: {
    text: fullResponse
  },
  quick_replies: intentData.quick_replies.map(reply => ({
    content_type: 'text',
    title: reply,
    payload: reply.toLowerCase().replace(/\s+/g, '_')
  }))
};

return responseData;

// Log automated interaction
const messageData = $node["Parse Instagram Message"].json;
const intentData = $node["Classify Intent"].json;

return {
  timestamp: new Date().toISOString(),
  platform: 'instagram',
  user_id: messageData.from,
  username: messageData.from_username,
  message_type: 'dm',
  original_message: messageData.text,
  intent_classified: intentData.intent,
  confidence: intentData.confidence,
  response_type: 'automated',
  matched_keywords: intentData.matched_keywords,
  response_sent: true
};

// Prepare human handoff response
const messageData = $node["Parse Instagram Message"].json;
const intentData = $node["Classify Intent"].json;

// Send initial response explaining handoff
const handoffResponse = {
  recipient_id: messageData.from,
  message: {
    text: intentData.response_text
  }
};

// Prepare data for human agent
const handoffData = {
  platform: 'instagram',
  user_id: messageData.from,
  username: messageData.from_username,
  original_message: messageData.text,
  intent: intentData.intent,
  confidence: intentData.confidence,
  priority: intentData.intent === 'suporte' || intentData.intent === 'devolucao' ? 'high' : 'medium',
  category: intentData.intent,
  timestamp: new Date().toISOString()
};

return {
  handoff_response: handoffResponse,
  handoff_data: handoffData
};

// Notify human agents about new handoff
const handoffData = $node["Prepare Human Handoff"].json.handoff_data;

// This would integrate with your notification system
// (Slack, WhatsApp Business, internal dashboard, etc.)

const notification = {
  text: `🤖 Novo handoff Instagram: ${handoffData.username} - ${handoffData.intent} (confiança: ${(handoffData.confidence * 100).toFixed(1)}%)`,
  priority: handoffData.priority,
  user_id: handoffData.user_id,
  platform: handoffData.platform
};

// Send to Slack or internal system
return notification;

// Handle invalid messages (empty, media-only, etc.)
const messageData = $node["Parse Instagram Message"].json;

let responseText = 'Olá! ';
let quickReplies = ['Ver produtos', 'Suporte', 'FAQs'];

if (messageData.intent === 'image_only') {
  responseText += 'Vejo que você enviou uma imagem! 📸 Como posso ajudar com isso?';
  quickReplies = ['Analisar imagem', 'Suporte técnico', 'Falar com humano'];
} else {
  responseText += 'Como posso ajudar você hoje? 😊';
}

return {
  recipient_id: messageData.from,
  message: {
    text: responseText
  },
  quick_replies: quickReplies.map(reply => ({
    content_type: 'text',
    title: reply,
    payload: reply.toLowerCase().replace(/\s+/g, '_')
  }))
};
